<?php
session_start();require_once '../shared/config.php';requireLogin('vendor','login.php');$db=getDB();$vendorId=(int)$_SESSION['vendor_id'];$storeName=$_SESSION['vendor_name'];$message='';$error='';
$occasionAlerts=[
 'Wedding'=>[10,11,12,1,2],'Haldi / Mehendi'=>[10,11,12,1,2],
 'Festival'=>[9,10,11],'College Fest'=>[8,9,1,2],'Traditional Day'=>[1,8,9],
 'Cultural Event'=>[1,8,9,10],'Photoshoot'=>[1,2,10,11,12]
];
$currentMonth=(int)date('n');$upcomingOccasions=[];foreach($occasionAlerts as $name=>$months){foreach($months as $m){if($m>=$currentMonth){$upcomingOccasions[]=$name;break;}}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='generate_ai'){
 o2oRequireCsrf();$key=getenv('OPENAI_API_KEY')?:'';
 if(!$key)$error='AI provider is not configured yet.';
 else{
  $dataset='Top items:\n';foreach($top as $r)$dataset.=$r['name'].' | '.$r['category'].' | demand '.$r['demand_count'].' | revenue ₹'.$r['revenue']."\n";
  $dataset.='Categories:\n';foreach($categories as $r)$dataset.=$r['category'].' | rentals '.$r['rental_orders'].' | revenue ₹'.$r['rental_revenue']."\n";
  $prompt="You are O2O Tradition vendor demand intelligence. Use ONLY the supplied observed rental data. Upcoming occasions are ".implode(', ',$upcomingOccasions).". Return ONLY valid JSON: insight (string), recommendations (array of short strings, max 6). Give evidence-based inventory/restock suggestions and occasion preparation ideas. Do not claim certainty or invent demand.";
  $payload=['model'=>getenv('O2O_AI_MODEL')?:'gpt-5.6-luna','input'=>[['role'=>'user','content'=>[['type'=>'input_text','text'=>$prompt."\n\n".$dataset]]]]];
  $ch=curl_init('https://api.openai.com/v1/responses');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>60]);$raw=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
  if($raw===false||$http<200||$http>=300)$error='AI request failed. Please try again.';
  else{$resp=json_decode($raw,true);$text=$resp['output_text']??'';if(!$text&&isset($resp['output']))foreach($resp['output'] as $o)foreach(($o['content']??[]) as $part)if(isset($part['text']))$text.=$part['text'];$data=json_decode(trim(str_replace(["```json","```"],'',$text)),true);
   if(!is_array($data)||!is_string($data['insight']??null))$error='AI returned an unreadable demand insight.';
   else{$recs=is_array($data['recommendations']??null)?array_values(array_filter(array_map('strval',$data['recommendations']))):[];$ins=$db->prepare("INSERT INTO demand_insights(vendor_id,insight,recommendations) VALUES(?,?,?)");$ins->execute([$vendorId,trim($data['insight']),json_encode(array_slice($recs,0,6),JSON_UNESCAPED_UNICODE)]);$message='AI demand insight generated.';}
  }
 }
}
$st=$db->prepare("SELECT i.category,COUNT(o.id) rental_orders,COALESCE(SUM(o.total_rent),0) rental_revenue FROM items i LEFT JOIN orders o ON o.item_id=i.id AND o.vendor_id=? AND o.status='completed' WHERE i.vendor_id=? GROUP BY i.category ORDER BY rental_orders DESC,rental_revenue DESC");$st->execute([$vendorId,$vendorId]);$categories=$st->fetchAll();
$st=$db->prepare("SELECT i.id,i.name,i.category,COUNT(o.id) demand_count,COALESCE(SUM(o.total_rent),0) revenue FROM items i LEFT JOIN orders o ON o.item_id=i.id AND o.vendor_id=? AND o.status IN ('in_progress','completed') WHERE i.vendor_id=? GROUP BY i.id,i.name,i.category ORDER BY demand_count DESC,revenue DESC LIMIT 10");$st->execute([$vendorId,$vendorId]);$top=$st->fetchAll();
$st=$db->prepare("SELECT COUNT(*) FROM orders WHERE vendor_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)");$st->execute([$vendorId]);$last30=(int)$st->fetchColumn();
$st=$db->prepare("SELECT COUNT(*) FROM orders WHERE vendor_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 90 DAY)");$st->execute([$vendorId]);$last90=(int)$st->fetchColumn();
$growth=$last90>0?round(($last30-($last90-$last30)/2)/max(1,(($last90-$last30)/2))*100):null;
$latestInsightStmt=$db->prepare("SELECT insight,recommendations,generated_at FROM demand_insights WHERE vendor_id=? ORDER BY generated_at DESC LIMIT 1");$latestInsightStmt->execute([$vendorId]);$latestInsight=$latestInsightStmt->fetch();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demand Intelligence – O2O Tradition</title><style>
body{font-family:Arial;background:#F4F7F4;margin:0;color:#1A2E1A}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;text-decoration:none;margin-left:18px}.main{max-width:1050px;margin:auto;padding:30px}.hero,.card{background:#fff;padding:22px;margin-bottom:18px;box-shadow:0 2px 10px #0001}.hero{background:#21170B;color:#fff}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stat{background:#fff;padding:18px;box-shadow:0 2px 10px #0001}.stat b{font-size:28px;display:block}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:13px}.badge{display:inline-block;padding:4px 8px;background:#FEF3C7;color:#92400E;border-radius:12px;font-size:11px}.small{font-size:12px;color:#777;line-height:1.6}@media(max-width:700px){.stats{grid-template-columns:1fr}.table{display:block;overflow:auto}}</style></head><body><div class="nav"><b>O2O Tradition · <?=htmlspecialchars($storeName)?></b><a href="dashboard.php">← Dashboard</a></div><main class="main"><?php if($message):?><div class="card" style="background:#D1FAE5;color:#065F46"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="card" style="background:#FEF2F2;color:#991B1B"><?=htmlspecialchars($error)?></div><?php endif;?><section class="hero"><h1>📈 Demand Intelligence</h1><p>Evidence-based inventory insights from your recorded rental activity. These figures describe observed demand; they are not forecasts.</p></section><section class="card"><h2>Upcoming occasion signals</h2><p class="small"><?= $upcomingOccasions ? htmlspecialchars(implode(' · ',$upcomingOccasions)) : 'No configured upcoming occasion signals remain this calendar year.' ?></p><form method="POST"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="generate_ai"><button style="padding:10px 15px;background:#0F1B2D;color:#C9A84C;border:0">✨ Generate AI Inventory Insight</button></form></section><?php if($latestInsight):$rec=json_decode($latestInsight['recommendations'],true)?:[];?><section class="card"><h2>Latest AI insight</h2><p class="small"><?=htmlspecialchars($latestInsight['insight'])?></p><?php if($rec):?><ul><?php foreach($rec as $x):?><li><?=htmlspecialchars($x)?></li><?php endforeach;?></ul><?php endif;?><p class="small">Generated <?=date('d M Y, h:i A',strtotime($latestInsight['generated_at']))?> from observed marketplace data.</p></section><?php endif;?><div class="stats"><div class="stat">📅<b><?=$last30?></b><small>Rental orders in last 30 days</small></div><div class="stat">📊<b><?=$last90?></b><small>Rental orders in last 90 days</small></div><div class="stat">💡<b><?=count($top)?></b><small>Top items tracked</small></div></div><section class="card"><h2>Top requested items</h2><?php if(!$top):?><p class="small">No completed or active rental demand is recorded yet.</p><?php else:?><table class="table"><tr><th>Item</th><th>Category</th><th>Demand</th><th>Rental revenue</th></tr><?php foreach($top as $i=>$r):?><tr><td><b><?=htmlspecialchars($r['name'])?></b> <?php if($i<3):?><span class="badge">High observed demand</span><?php endif;?></td><td><?=htmlspecialchars($r['category']?:'Uncategorised')?></td><td><?=intval($r['demand_count'])?></td><td>₹<?=number_format((float)$r['revenue'],0)?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="card"><h2>Category demand</h2><?php if(!$categories):?><p class="small">Category-level demand will appear after rental activity is recorded.</p><?php else:?><table class="table"><tr><th>Category</th><th>Completed rentals</th><th>Rental revenue</th></tr><?php foreach($categories as $r):?><tr><td><?=htmlspecialchars($r['category']?:'Uncategorised')?></td><td><?=intval($r['rental_orders'])?></td><td>₹<?=number_format((float)$r['rental_revenue'],0)?></td></tr><?php endforeach;?></table><?php endif;?></section><section class="card"><h2>How to use this</h2><p class="small">Use high observed-demand items/categories as signals when deciding what to restock, photograph, promote or make available for upcoming occasions. The current version uses your recorded marketplace data only; it does not invent demand or claim future demand.</p></section></main></body></html>